// Browser polyfills for Node.js APIs
if (typeof global === 'undefined') {
  window.global = window;
}

if (typeof process === 'undefined') {
  window.process = {
    env: {
      NODE_ENV: process?.env?.NODE_ENV || 'production'
    },
    version: '',
    versions: {},
    platform: 'browser',
    browser: true,
    argv: [],
    title: 'browser',
    pid: 1,
    stdout: {},
    stderr: {},
    stdin: {},
    nextTick: function(callback) {
      setTimeout(callback, 0);
    },
    cwd: function() {
      return '/';
    },
    chdir: function() {},
    umask: function() {
      return 0;
    }
  };
}

if (typeof Buffer === 'undefined') {
  window.Buffer = {
    isBuffer: function() {
      return false;
    },
    from: function() {
      return [];
    },
    alloc: function() {
      return [];
    }
  };
}

export default {};
